/* Generated build substitutes an immutable shell version and exact asset list. */
const CACHE_PREFIX = "card-game-shell-";
const CACHE_NAME = CACHE_PREFIX + __SHELL_VERSION__;
const PRECACHE = __PRECACHE__;
const SHELL_URL = new URL("./index.html", self.registration.scope).href;

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    try {
      // Install is atomic from the application's point of view. A broken asset
      // rejects the new worker, so the previous working shell remains active.
      await cache.addAll(PRECACHE.map((path) => new Request(new URL(path, self.registration.scope), { cache: "reload" })));
      await self.skipWaiting();
    } catch (error) {
      await caches.delete(CACHE_NAME);
      throw error;
    }
  })());
});
self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const owned = (await caches.keys()).filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME);
    // Keep the previous version for tabs still using its hashed JS/CSS.
    await Promise.all(owned.slice(0, -1).map((key) => caches.delete(key)));
    await self.clients.claim();
  })());
});
self.addEventListener("fetch", (event) => {
  const request = event.request;
  const url = new URL(request.url);
  const scope = new URL(self.registration.scope);
  if (request.method !== "GET" || url.origin !== scope.origin || !url.pathname.startsWith(scope.pathname)) return;
  if (request.mode === "navigate") {
    event.respondWith((async () => {
      try {
        const response = await fetch(request, { cache: "no-store" });
        if (response.ok) return response;
      } catch { /* Use a complete, version-consistent offline shell. */ }
      return (await (await caches.open(CACHE_NAME)).match(SHELL_URL)) ?? Response.error();
    })());
    return;
  }
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    const cached = await cache.match(request);
    if (cached) return cached;
    try {
      return await fetch(request);
    } catch {
      for (const key of await caches.keys()) {
        if (!key.startsWith(CACHE_PREFIX)) continue;
        const older = await (await caches.open(key)).match(request);
        if (older) return older;
      }
      // Never substitute HTML for a missing script/image request.
      return Response.error();
    }
  })());
});

export const BATTLEFIELD = { width: 1152, height: 648 } as const;
export interface ViewportTransform {
  scale: number; offsetX: number; offsetY: number;
  visible: { x: number; y: number; width: number; height: number };
}
export function battlefieldTransform(width: number, height: number): ViewportTransform {
  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) throw new Error("Invalid viewport dimensions");
  const scale = Math.max(width / BATTLEFIELD.width, height / BATTLEFIELD.height);
  const offsetX = (width - BATTLEFIELD.width * scale) / 2;
  const offsetY = (height - BATTLEFIELD.height * scale) / 2;
  return { scale, offsetX, offsetY, visible: { x: -offsetX / scale, y: -offsetY / scale, width: width / scale, height: height / scale } };
}
export function worldToScreen(t: ViewportTransform, x: number, y: number) {
  return { x: t.offsetX + x * t.scale, y: t.offsetY + y * t.scale };
}
export function screenToWorld(t: ViewportTransform, x: number, y: number) {
  return { x: (x - t.offsetX) / t.scale, y: (y - t.offsetY) / t.scale };
}
/** V2 fixed architectural sockets must use these image-space anchors. */
export const FIXED_SOCKETS = { deck: { x: 180, y: 258 }, endTurn: { x: 1008, y: 258 }, scene: { x: 576, y: 270 } } as const;

import type { BasicGameSession } from "../core/basic-game.js";

export type ChangeReason = "command" | "new-game" | "external";
export type SessionListener = (reason: ChangeReason) => void;

/** One owner. Commands mutate drafts, and an error cannot commit a partial turn. */
export class GameStore {
  private state: BasicGameSession;
  private listeners = new Set<SessionListener>();
  private notifying = false;
  private dirty = false;

  constructor(initial: BasicGameSession, private readonly persist: (state: BasicGameSession) => void = () => { }) {
    this.state = structuredClone(initial);
  }

  read(): BasicGameSession { return structuredClone(this.state); }
  subscribe(listener: SessionListener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  dispatch(reduce: (draft: BasicGameSession) => string | null): string | null {
    if (this.notifying) return "状态正在同步，请稍后再试。";
    const draft = this.read();
    const error = reduce(draft);
    if (error) return error;
    this.commit(draft, "command");
    return null;
  }

  replace(next: BasicGameSession): void { this.commit(structuredClone(next), "new-game"); }

  acceptExternal(next: BasicGameSession): boolean {
    if (next.updatedAt <= this.state.updatedAt) return false;
    this.state = structuredClone(next);
    this.dirty = false;
    this.notify("external");
    return true;
  }

  flush(): void {
    if (!this.dirty) return;
    this.persist(this.read());
    this.dirty = false;
  }

  private commit(draft: BasicGameSession, reason: ChangeReason): void {
    draft.revision = (this.state.revision ?? 0) + 1;
    const previous = Date.parse(this.state.updatedAt);
    draft.updatedAt = new Date(Math.max(Date.now(), Number.isFinite(previous) ? previous + 1 : 0)).toISOString();
    this.state = draft;
    this.dirty = true;
    // Storage failures do not roll back a valid move. The adapter reports them;
    // the store retains a dirty snapshot for the next explicit flush.
    try { this.flush(); } catch { /* Keep the dirty flag. */ }
    this.notify(reason);
  }

  private notify(reason: ChangeReason): void {
    this.notifying = true;
    try {
      for (const listener of this.listeners) {
        try { listener(reason); }
        catch (error) { console.error("Session subscriber failed after commit", error); }
      }
    }
    finally { this.notifying = false; }
  }
}

import type { BasicGameSession } from "../core/basic-game.js";
import type { PendingUnitEffect } from "../core/deathrattle-effects.js";
import { isPendingEffect } from "./validation.js";

/** Import pending choices only. Historical death logs must never replay. */
export function migrateLegacyEffects(session: BasicGameSession, raw: string | null): void {
  session.pendingEffects ??= [];
  if (session.revision !== undefined || !raw) return;
  try {
    const legacy = JSON.parse(raw);
    if (legacy.gameId !== session.gameId || !Array.isArray(legacy.queue)) return;
    for (const effect of legacy.queue) {
      if (!isPendingEffect({ ...effect, kind: "unit" })) continue;
      if (session.pendingEffects.some((entry) => entry.id === effect.id)) continue;
      session.pendingEffects.push({ ...effect, kind: "unit" } as PendingUnitEffect);
    }
  } catch { /* Leave the original legacy key untouched for recovery. */ }
}

import type { BasicGameSession } from "../core/basic-game.js";

const isRecord = (x: unknown): x is Record<string, unknown> => typeof x === "object" && x !== null && !Array.isArray(x);
const text = (x: unknown): x is string => typeof x === "string";
const strings = (x: unknown): x is string[] => Array.isArray(x) && x.every(text);
const integer = (x: unknown): boolean => typeof x === "number" && Number.isInteger(x) && x >= 0;
const finite = (x: unknown): boolean => typeof x === "number" && Number.isFinite(x);
const player = (x: unknown): boolean => x === "P1" || x === "P2";
const time = (x: unknown): boolean => text(x) && Number.isFinite(Date.parse(x));
const optional = (x: unknown, check: (v: unknown) => boolean): boolean => x === undefined || check(x);

export function isPendingEffect(x: unknown): boolean {
  if (!isRecord(x) || !text(x.id) || !player(x.sourcePlayer) || !text(x.sourceCardId)
    || !text(x.sourceName) || !integer(x.remainingTargets)) return false;
  if (x.kind === "unit") return ["damage", "health_loss", "heal", "attack_buff"].includes(String(x.action))
    && ["all_units", "all_minions", "enemy_units", "enemy_minions", "friendly_units", "friendly_minions"].includes(String(x.scope))
    && finite(x.amount) && (x.amount as number) > 0 && strings(x.selectedKeys) && text(x.text);
  return ["freeze", "petrify"].includes(String(x.kind)) && player(x.targetPlayer)
    && integer(x.durationOwnTurns) && (x.durationOwnTurns as number) > 0 && strings(x.selectedTargetIds);
}

function isMinion(x: unknown): boolean {
  if (!isRecord(x) || !text(x.instanceId) || !text(x.cardId) || !player(x.owner) || !player(x.controller)
    || !finite(x.currentHealth) || !finite(x.attackModifier) || !integer(x.attacksUsedThisTurn)
    || !integer(x.summonedOnTurn) || !Array.isArray(x.statuses)) return false;
  return x.statuses.every((status: unknown) => isRecord(status) && text(status.keyword)
    && ["charges", "remainingOwnTurns", "activeFromOwnTurn", "expiresAfterOwnTurn"].every((key) => optional(status[key], integer))
    && optional(status.sourceCardId, text));
}

/** Validate disk input before any view or command reads nested fields. v1 remains supported. */
export function isSession(x: unknown): x is BasicGameSession {
  if (!isRecord(x) || x.schemaVersion !== 1 || !text(x.gameId) || !time(x.createdAt) || !time(x.updatedAt)
    || typeof x.handoffRequired !== "boolean" || !isRecord(x.turnsStarted) || !isRecord(x.state)
    || !optional(x.revision, integer) || !optional(x.demoSpecialsAdded, (v) => typeof v === "boolean")) return false;
  const state = x.state;
  if (!integer(state.turn) || (state.turn as number) < 1 || !player(state.activePlayer)
    || !(state.firstPlayer === null || player(state.firstPlayer)) || !strings(state.sharedDeck)
    || ![null, "P1", "P2", "draw"].includes(state.winner as null | string) || !isRecord(state.players)
    || !Array.isArray(state.deathLog) || !Array.isArray(x.log)) return false;
  for (const id of ["P1", "P2"]) {
    const p = state.players[id];
    if (!isRecord(p) || p.id !== id || !finite(p.health) || !strings(p.hand) || !strings(p.discardPile)
      || !Array.isArray(p.board) || p.board.length !== 5 || !p.board.every((m) => m === null || isMinion(m))
      || !Array.isArray(p.overflowMinions) || !p.overflowMinions.every(isMinion)
      || !integer(p.normalSummonsUsedThisTurn) || !integer(x.turnsStarted[id])
      || !(p.equipment === null || text(p.equipment)) || !(p.scene === null || text(p.scene))) return false;
  }
  if (!state.deathLog.every((d) => isRecord(d) && integer(d.turn) && player(d.owner) && text(d.cardId)
    && text(d.instanceId) && ["damage", "sacrifice", "execution", "other"].includes(String(d.cause))
    && typeof d.canRevive === "boolean" && optional(d.controllerAtDeath, player)
    && optional(d.deathrattleSuppressed, (v) => typeof v === "boolean"))) return false;
  if (!x.log.every((l) => isRecord(l) && text(l.at) && integer(l.turn) && text(l.text))) return false;
  return x.pendingEffects === undefined || (Array.isArray(x.pendingEffects) && x.pendingEffects.every(isPendingEffect));
}
